241		content = clean(content)
242		constraints = clean(constraints)
243		followOwner = clean(followOwner)
244		if err := requireNonEmpty("事项内容", content); err != nil {
245			return Item{}, err
246		}
247		if err := requireNonEmpty("后续负责人", followOwner); err != nil {
248			return Item{}, err
249		}
250		if !severity.valid() {
251			return Item{}, fmt.Errorf("%w：严重程度无效", ErrInvalidInput)
252		}
253	
254		var created Item
255		err := svc.store.mutate(func(d *Data) error {
256			sh, _ := findShift(d, shiftID)
257			if sh == nil {
258				return fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
259			}
260			if sh.Closed {
261				return fmt.Errorf("%w：班次 %s 已结束，不能新增事项", ErrShiftClosed, sh.ID)
262			}
263			d.ItemSeq++
264			now := svc.now()
265			created = Item{
266				ID:             fmt.Sprintf("I%03d", d.ItemSeq),
267				OriginShiftID:  sh.ID,
268				ShiftIDs:       []string{sh.ID},
269				CurrentShiftID: sh.ID,
270				Content:        content,
271				Severity:       severity,
272				Constraints:    constraints,
273				FollowOwner:    followOwner,
274				CreatedAt:      now,
275				Events: []ItemEvent{
276					{At: now, Kind: "created", Detail: "事项建立"},
277				},
278			}
279			d.Items = append(d.Items, created)
280			return nil
281		})
282		if err != nil {
283			return Item{}, err
284		}
285		// 返回独立副本：调用方保留的新增结果与系统保存的事项脱离，
286		// 改动结果不影响存储，也不会在后续正常保存时被带进存储。
287		return cloneItem(created), nil
288	}
