472	// CreateHandover 由交班班次向同岗位接班班次发起交接。
473	// 重复向同一接班班次发起返回已有记录（ErrHandoverExists）；该承诺在接班班次
474	// 随后结束、事项已在后续班次关闭或继续流转后仍然成立，返回保存的原交接内容，
475	// 不重新挑选清单、不重新接收或移动事项、不追加经过。改换接班对象报
476	// ErrHandoverTarget 并指出原接班班次，无论新对象是否结束都不产生第二条交接。
477	// 不存在的班次编号与交给自身始终按各自错误拒绝；同岗位及接班班次尚未结束等
478	// 要求仅对首次发起生效。
479	// 只有本地数据保存成功才算发起完成：首次发起的输入与班次状态均合法、实际进入
480	// 保存阶段后写盘失败时，内存变更随快照一并回滚，返回原保存错误与零值交接结果
481	// （编号、岗位、两班编号为空，发起时间为零值，完成时间为空，清单没有事项），
482	// 不把尚未保存的编号、发起时间、清单或空清单的完成时间当作发起结果；失败尝试
483	// 不占用交接编号，也不留下已指定接班对象的关系。
484	func (svc *Service) CreateHandover(fromShiftID, toShiftID string) (Handover, error) {
485		fromShiftID = clean(fromShiftID)
486		toShiftID = clean(toShiftID)
487	
488		var result Handover
489		// saved 标记业务变更是否已完整执行、只待落盘：此后出现的错误只能是保存
490		// 阶段失败，而不是业务拒绝。
491		saved := false
492		err := svc.store.mutate(func(d *Data) error {
493			from, _ := findShift(d, fromShiftID)
494			to, _ := findShift(d, toShiftID)
495			if from == nil {
496				return fmt.Errorf("%w：交班班次 %s", ErrNotFound, fromShiftID)
497			}
498			if to == nil {
499				return fmt.Errorf("%w：接班班次 %s", ErrNotFound, toShiftID)
500			}
501			if from.ID == to.ID {
502				return fmt.Errorf("%w：交班班次与接班班次不能都是 %s", ErrSameShift, from.ID)
503			}
504			// 同一交班班次只能指定一个接班对象。重复发起（包括接班班次随后已
505			// 结束、事项已在后续班次关闭或继续流转的情况）一律返回保存的原记录，
506			// 不重新接收事项、不追加经过；改换为另一个确实存在的接班对象（无论其
507			// 是否结束、是否同岗位）都按改换对象报错并指出原接班班次，且不能生成
508			// 第二条交接。该判定先于同岗位、接班班次状态等首次发起校验；编号不
509			// 存在与交给自身的校验仍在其前。
510			for i := range d.Handovers {
511				if d.Handovers[i].FromShiftID == from.ID {
512					existing := &d.Handovers[i]
513					// 即使以“已存在”错误返回，交出的也是独立副本，调用方改动
514					// 不影响系统保存的原交接记录。
515					result = cloneHandover(*existing)
516					if existing.ToShiftID != to.ID {
517						return fmt.Errorf("%w：交班班次 %s 已指定接班班次 %s，不能改换为 %s",
518							ErrHandoverTarget, from.ID, existing.ToShiftID, to.ID)
519					}
520					return fmt.Errorf("%w：交接 %s", ErrHandoverExists, existing.ID)
521				}
522			}
523	
524			if from.Position != to.Position {
525				return fmt.Errorf("%w：班次 %s（%s）不能交给其他岗位 %s（%s）",
526					ErrPositionMismatch, from.ID, from.Position, to.ID, to.Position)
527			}
528	
529			// 以下为首次发起的要求：接班班次尚未结束、开始时间不早于交班班次、
530			// 交班班次已经结束，重叠区间须有有效说明（正文去掉首尾空白后仍有内容，
531			// 只凭说明记录存在不算）。
532			if to.Closed {
533				return fmt.Errorf("%w：接班班次 %s 已结束，不能交接", ErrShiftClosed, to.ID)
534			}
535			if to.Start.Before(from.Start) {
536				return fmt.Errorf("%w：接班班次 %s 开始时间 %s 早于交班班次 %s 开始时间 %s",
537					ErrInvalidInput, to.ID, to.Start.Format(time.RFC3339),
538					from.ID, from.Start.Format(time.RFC3339))
539			}
540			if !from.Closed {
541				return fmt.Errorf("%w：交班班次 %s 尚未结束，结束班次后未关闭事项才成为交接清单",
542					ErrShiftNotClosed, from.ID)
543			}
544			if intervalsOverlap(from.Start, from.End, to.Start, to.End) && !hasEffectiveNote(d, from.ID, to.ID) {
545				return fmt.Errorf("%w：交班班次 %s 与接班班次 %s 时间区间重叠，须先填写重叠说明",
546					ErrOverlap, from.ID, to.ID)
547			}
548	
549			entries := []HandoverEntry{}
550			for i := range d.Items {
551				it := &d.Items[i]
552				if it.CurrentShiftID == from.ID && !it.Closed {
553					entries = append(entries, HandoverEntry{
554						ItemID:      it.ID,
555						Content:     it.Content,
556						Severity:    it.Severity,
557						Constraints: it.Constraints,
558						FollowOwner: it.FollowOwner,
559						Status:      EntryPending,
560					})
561				}
562			}
563			sort.Slice(entries, func(i, j int) bool { return entries[i].ItemID < entries[j].ItemID })
564	
565			d.HandoverSeq++
566			now := svc.now()
567			h := Handover{
568				ID:          fmt.Sprintf("H%03d", d.HandoverSeq),
569				Position:    from.Position,
570				FromShiftID: from.ID,
571				ToShiftID:   to.ID,
572				CreatedAt:   now,
573				Entries:     entries,
574			}
575			if len(entries) == 0 {
576				// 空清单直接完成。
577				h.CompletedAt = &now
578			}
579			d.Handovers = append(d.Handovers, h)
580			result = cloneHandover(h)
581			saved = true
582			return nil
583		})
584		if err != nil {
585			if saved {
586				// 业务校验全部通过、实际进入保存阶段后失败：内存已随快照回滚，
587				// 不能把尚未保存的新交接（编号、发起时间、清单与空清单的完成时间）
588				// 当作发起结果交给调用方。
589				return Handover{}, err
590			}
591			// 业务拒绝：重复发起与改换对象仍按承诺返回保存的原记录。
592			return result, err
593		}
594		return result, nil
595	}
596	
597	// ProcessEntry 由接班人逐项处理交接事项，须填写操作人。
598	// action 为 confirm（确认接收）、return（退回，须填原因）或 track（继续跟踪，须填跟踪说明和后续负责人）。
599	// 已退回项表示等待交班人补充，只有在原交接记录上成功重新提交、恢复待处理后才能再次
600	// 确认、继续跟踪或退回；未重新提交前直接处理一律返回状态错误，且不改变任何数据。
601	// 最后一项成功接收使整份交接首次全部明确接收时，完成时间记为本次成功处理时间；
602	// 若记录里存在补齐前误写（或零值）的旧完成时间，一并以本次时间覆盖。本次处理失败、
603	// 退回或仍有未接收项时不写完成时间，交接不能提前完成。
604	// 只有本地数据保存成功才算处理完成：输入合法、该项允许处理、实际进入保存阶段后
605	// 写盘失败时，内存变更随快照一并回滚，返回原保存错误与零值交接结果（编号、岗位、
606	// 两班编号为空，发起时间为零值，完成时间为空，清单没有事项），不把本次尝试形成的
607	// 处理状态、操作人、处理时间或交接完成时间当作处理结果，也不返回失败前的整份交接；
608	// 最后一项的保存失败同样不能通过返回结果宣称整份交接完成。
609	func (svc *Service) ProcessEntry(handoverID, itemID string, action EntryAction, operator, reason, trackingNote, nextFollowOwner string) (Handover, error) {
610		handoverID = clean(handoverID)
611		itemID = clean(itemID)
612		operator = clean(operator)
613		reason = clean(reason)
614		trackingNote = clean(trackingNote)
615		nextFollowOwner = clean(nextFollowOwner)
616	
617		if action != ActionConfirm && action != ActionReturn && action != ActionTrack {
618			return Handover{}, fmt.Errorf("%w：未知操作 %q", ErrInvalidInput, action)
619		}
620		if err := requireNonEmpty("操作人", operator); err != nil {
621			return Handover{}, err
622		}
623	
624		var result Handover
625		err := svc.store.mutate(func(d *Data) error {
626			h, _ := findHandover(d, handoverID)
627			if h == nil {
628				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
629			}
630			e, _ := findEntry(h, itemID)
631			if e == nil {
632				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
633			}
634			if e.Status.Received() {
635				return fmt.Errorf("%w：事项 %s 已%s，不能重复处理或退回",
636					ErrHandoverState, e.ItemID, e.Status.Label())
637			}
638			if e.Status == EntryReturned {
639				// 退回表示等待交班人补充：必须先在原交接记录上补充说明并重新提交，
640				// 该项恢复待处理后才能再次确认、继续跟踪或退回。即使本次填写了
641				// 操作人、退回原因或跟踪说明，也不能跳过这一步。
642				return fmt.Errorf("%w：事项 %s 已退回，正等待交班人补充说明并在原交接记录 %s 上重新提交；请先完成补充并重新提交后再处理",
643					ErrHandoverState, e.ItemID, h.ID)
644			}
645			switch action {
646			case ActionReturn:
647				if err := requireNonEmpty("退回原因", reason); err != nil {
648					return err
649				}
650			case ActionTrack:
651				if err := requireNonEmpty("跟踪说明", trackingNote); err != nil {
652					return err
653				}
654				if err := requireNonEmpty("后续负责人", nextFollowOwner); err != nil {
655					return err
656				}
657			}
658	
659			now := svc.now()
660			switch action {
661			case ActionConfirm:
662				e.Status = EntryConfirmed
663			case ActionTrack:
664				e.Status = EntryTracking
665				e.TrackingNote = trackingNote
666				e.FollowOwner = nextFollowOwner
667			case ActionReturn:
668				e.Status = EntryReturned
669				e.Rounds = append(e.Rounds, ReturnRound{
670					Seq:            len(e.Rounds) + 1,
671					ReturnedAt:     now,
672					ReturnOperator: operator,
673					Reason:         reason,
674				})
675			}
676			e.Operator = operator
677			e.ProcessedAt = &now
678	
679			if action != ActionReturn {
680				// 确认与继续跟踪都进入接班班次的未关闭清单，保留原编号与历史。
681				if it, _ := findItem(d, e.ItemID); it != nil && it.CurrentShiftID == h.FromShiftID {
682					it.CurrentShiftID = h.ToShiftID
683					if !contains(it.ShiftIDs, h.ToShiftID) {
684						it.ShiftIDs = append(it.ShiftIDs, h.ToShiftID)
685					}
686					detail := receivedDetailText(h, action, e.Status.Label(), trackingNote, nextFollowOwner)
687					if action == ActionTrack {
688						// 继续跟踪指定新的后续负责人，回写到事项并保留跟踪说明。
689						it.FollowOwner = nextFollowOwner
690					}
691					it.Events = append(it.Events, ItemEvent{At: now, Kind: "received", Operator: operator, Detail: detail})
692				}
693			}
694	
695			if h.Completed() {
696				// 完成时间记录这份交接真正接收齐全部事项的时刻：以最后一次成功
697				// 接收（确认或继续跟踪）的处理时间为准。旧数据可能在清单仍有结果
698				// 缺失、无法识别、待处理或退回项时就误写过完成时间（或只留下零值）：
699				// 接班人逐项补齐、整份交接首次全部明确接收时，用本次成功处理时间
700				// 覆盖那个旧时间，不能沿用补齐前的时刻；旧时间缺失（nil）时同样在
701				// 本次补上。未全部接收（如本次退回、仍有异常结果项）时不写入，
702				// 交接保持未完成。正常流程与空清单在首次全部接收时写入，之后已接收
703				// 项无法再处理，完成时间不会被改写。
704				h.CompletedAt = &now
705			}
706			// 返回独立副本：调用方保留的处理结果（含逐项处理时间、退回/补充记录
707			// 与完成时间）不与系统保存的交接共享内存。
708			result = cloneHandover(*h)
709			return nil
710		})
711		if err != nil {
712			// 业务拒绝或保存失败都不返回任何交接结果：保存失败时内存已随快照
713			// 回滚，不能把本次尝试形成但尚未保存的处理状态、操作人、处理时间
714			// 或交接完成时间当作处理结果交给调用方。
715			return Handover{}, err
716		}
717		return result, nil
718	}
719	
720	// validProcessedAt 报告处理时间是否真实记录：nil 或零值
721	// （0001-01-01T00:00:00Z）都视为未记录，不推测补齐。
722	func validProcessedAt(t *time.Time) bool { return t != nil && !t.IsZero() }
723	
724	func contains(xs []string, x string) bool {
725		for _, v := range xs {
726			if v == x {
727				return true
728			}
729		}
730		return false
731	}
732	
733	// ResubmitReturned 由交班人对退回项追加非空说明并在同一交接记录上重新提交；
734	// 补充写入最近一次退回记录（保留该轮原因、退回人和退回时间，并记录补充人、
735	// 补充时间与重新提交时间），以前各轮说明不覆盖。只有该项恢复待处理，当前结果的
736	// 接班处理人与处理时间显示为尚未处理；原文、严重程度、限制条件不变，事项仍留在
737	// 交班班次，同一交接的其他事项不受影响。重新提交本身不表示接收。
738	// 对待处理、已确认或继续跟踪的事项重新提交报状态错误，不写入补充说明。
739	func (svc *Service) ResubmitReturned(handoverID, itemID, operator, supplement string) (Handover, error) {
740		handoverID = clean(handoverID)
741		itemID = clean(itemID)
742		operator = clean(operator)
743		supplement = clean(supplement)
744		if err := requireNonEmpty("操作人", operator); err != nil {
745			return Handover{}, err
746		}
747		if err := requireNonEmpty("补充说明", supplement); err != nil {
748			return Handover{}, err
749		}
750	
751		var result Handover
752		err := svc.store.mutate(func(d *Data) error {
753			h, _ := findHandover(d, handoverID)
754			if h == nil {
755				return fmt.Errorf("%w：交接 %s", ErrNotFound, handoverID)
756			}
757			e, _ := findEntry(h, itemID)
758			if e == nil {
759				return fmt.Errorf("%w：交接 %s 中没有事项 %s", ErrNotFound, h.ID, itemID)
760			}
761			if e.Status != EntryReturned {
762				return fmt.Errorf("%w：事项 %s 当前状态为 %s，只有退回项可以补充说明后重新提交",
763					ErrHandoverState, e.ItemID, e.Status.Label())
764			}
765			if len(e.Rounds) == 0 {
766				return fmt.Errorf("%w：事项 %s 缺少退回记录", ErrHandoverState, e.ItemID)
767			}
768			round := &e.Rounds[len(e.Rounds)-1]
769			if round.ResubmittedAt != nil {
770				return fmt.Errorf("%w：事项 %s 已重新提交，等待接班人处理", ErrHandoverState, e.ItemID)
771			}
772			now := svc.now()
773			round.Supplement = supplement
774			round.SupplementOperator = operator
775			round.SupplementAt = &now
776			round.ResubmittedAt = &now
777			// 仅这一个事项恢复待处理：当前结果的接班处理人与处理时间显示为
778			// 尚未处理；上一轮退回信息仍完整保留在 Rounds 历史中。
779			e.Status = EntryPending
780			e.Operator = ""
781			e.ProcessedAt = nil
782			// 返回独立副本：调用方保留的重新提交结果不与系统保存的交接共享内存。
783			result = cloneHandover(*h)
784			return nil
785		})
786		return result, err
787	}
788	
789	// GetShift 按编号查询班次。返回独立副本：改动结果不影响系统保存的记录。
790	func (svc *Service) GetShift(id string) (Shift, error) {
791		sh, _ := findShift(&svc.store.data, clean(id))
792		if sh == nil {
793			return Shift{}, fmt.Errorf("%w：班次 %s", ErrNotFound, id)
794		}
795		return cloneShift(*sh), nil
796	}
797	
798	// ListShifts 返回全部班次，按编号排序；每个班次都是独立副本。
799	func (svc *Service) ListShifts() []Shift {
800		out := make([]Shift, len(svc.store.data.Shifts))
801		for i, sh := range svc.store.data.Shifts {
802			out[i] = cloneShift(sh)
803		}
804		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
805		return out
806	}
807	
808	// GetItem 按稳定编号查询事项。返回独立副本：流经班次、历史事件与关闭时间
809	// 都与存储中的记录脱离，改动结果不影响系统保存的记录。
810	func (svc *Service) GetItem(id string) (Item, error) {
811		it, _ := findItem(&svc.store.data, clean(id))
812		if it == nil {
813			return Item{}, fmt.Errorf("%w：事项 %s", ErrNotFound, id)
814		}
815		return cloneItem(*it), nil
816	}
817	
818	// GetHandover 按编号查询交接。返回独立副本：清单各项（含处理时间与历次
819	// 退回/补充记录）与完成时间都与存储中的记录脱离，改动结果不影响系统保存的记录。
820	func (svc *Service) GetHandover(id string) (Handover, error) {
821		h, _ := findHandover(&svc.store.data, clean(id))
822		if h == nil {
823			return Handover{}, fmt.Errorf("%w：交接 %s", ErrNotFound, id)
824		}
825		return cloneHandover(*h), nil
826	}
827	
828	// ListHandovers 返回全部交接记录，按编号排序；每份交接都是独立副本。
829	func (svc *Service) ListHandovers() []Handover {
830		out := make([]Handover, len(svc.store.data.Handovers))
831		for i, h := range svc.store.data.Handovers {
832			out[i] = cloneHandover(h)
833		}
834		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
835		return out
836	}
837	
838	// OverlapNotes 返回涉及指定班次的全部重叠说明。
839	func (svc *Service) OverlapNotes(shiftID string) []OverlapNote {
840		shiftID = clean(shiftID)
841		out := []OverlapNote{}
842		for _, n := range svc.store.data.Notes {
843			if n.ShiftA == shiftID || n.ShiftB == shiftID {
844				out = append(out, n)
845			}
846		}
847		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
848		return out
849	}
850	
851	// cloneTimePtr 复制时间指针，nil 保持 nil。
852	func cloneTimePtr(t *time.Time) *time.Time {
853		if t == nil {
854			return nil
855		}
856		v := *t
857		return &v
858	}
859	
860	// cloneItem 深拷贝事项：流经班次、历史事件与关闭时间都与存储中的记录脱离。
861	func cloneItem(it Item) Item {
862		out := it
863		out.ShiftIDs = append([]string(nil), it.ShiftIDs...)
864		out.Events = append([]ItemEvent(nil), it.Events...)
865		out.ClosedAt = cloneTimePtr(it.ClosedAt)
866		return out
867	}
868	
869	// cloneCloseItemSnapshot 深拷贝结束时事项快照（含关闭时间指针）。
870	func cloneCloseItemSnapshot(s CloseItemSnapshot) CloseItemSnapshot {
871		out := s
872		out.ClosedAt = cloneTimePtr(s.ClosedAt)
873		return out
874	}
875	
876	// cloneCloseRecord 深拷贝班次结束时记录；nil 保持 nil，
877	// 空清单仍是非 nil 记录，与缺少结束时记录的旧数据相区别。
878	func cloneCloseRecord(rec *ShiftCloseRecord) *ShiftCloseRecord {
879		if rec == nil {
880			return nil
881		}
882		out := &ShiftCloseRecord{}
883		if rec.Items != nil {
884			out.Items = make([]CloseItemSnapshot, len(rec.Items))
885			for i, s := range rec.Items {
886				out.Items[i] = cloneCloseItemSnapshot(s)
887			}
888		}
889		return out
890	}
891	
892	// cloneShift 深拷贝班次：关闭时间与结束时记录都与存储中的记录脱离。
893	func cloneShift(sh Shift) Shift {
894		out := sh
895		out.ClosedAt = cloneTimePtr(sh.ClosedAt)
896		out.CloseRecord = cloneCloseRecord(sh.CloseRecord)
897		return out
898	}
899	
900	// cloneEntry 深拷贝交接单项：处理时间与历次退回/补充记录都与存储中的记录脱离。
901	func cloneEntry(e HandoverEntry) HandoverEntry {
902		out := e
903		out.ProcessedAt = cloneTimePtr(e.ProcessedAt)
904		if e.Rounds != nil {
905			out.Rounds = make([]ReturnRound, len(e.Rounds))
906			for i, r := range e.Rounds {
907				out.Rounds[i] = r
908				out.Rounds[i].SupplementAt = cloneTimePtr(r.SupplementAt)
909				out.Rounds[i].ResubmittedAt = cloneTimePtr(r.ResubmittedAt)
910			}
911		}
912		return out
913	}
914	
915	// cloneHandover 深拷贝交接记录：完成时间与清单各项都与存储中的记录脱离。
916	func cloneHandover(h Handover) Handover {
917		out := h
918		out.CompletedAt = cloneTimePtr(h.CompletedAt)
919		if h.Entries != nil {
920			out.Entries = make([]HandoverEntry, len(h.Entries))
921			for i, e := range h.Entries {
922				out.Entries[i] = cloneEntry(e)
923			}
924		}
925		return out
926	}
927	
928	// ShiftReport 按班次汇总完整事项、关闭情况、接班对象、每项交接当前结果与历次退回/补充说明。
929	// 进行中的班次展示当前事项；已结束班次展示结束时冻结的事项记录，
930	// 旧数据中缺少结束时记录的班次只展示当前事项并标明历史不完整。
931	// 返回的报告是查询当时的独立副本：班次信息、事项清单、结束时记录、最新状态
932	// 对照、关联交接与各项结果（含关闭时间、处理时间与历次退回补充记录）全部深拷贝，
933	// 调用方改动报告不影响系统保存的数据与其他已取得的报告，系统随后的正常处理
934	// 也不会改写这份报告；再次查询才反映最新内容。
935	func (svc *Service) ShiftReport(shiftID string) (ShiftReport, error) {
936		shiftID = clean(shiftID)
937		d := &svc.store.data
938		rep := ShiftReport{Results: map[string][]EntryView{}, LatestItems: map[string]Item{}}
939		sh, _ := findShift(d, shiftID)
940		if sh == nil {
941			return ShiftReport{}, fmt.Errorf("%w：班次 %s", ErrNotFound, shiftID)
942		}
943		rep.Shift = cloneShift(*sh)
944	
945		for _, n := range d.Notes {
946			if n.ShiftA == sh.ID || n.ShiftB == sh.ID {
947				rep.OverlapNotes = append(rep.OverlapNotes, n)
948			}
949		}
950		sort.Slice(rep.OverlapNotes, func(i, j int) bool { return rep.OverlapNotes[i].ID < rep.OverlapNotes[j].ID })
951	
952		switch {
953		case !sh.Closed:
954			// 进行中的班次：事项可继续修改、关闭，展示当前信息。
955			rep.Items = currentItemsOfShift(d, sh.ID)
956		case sh.CloseRecord != nil:
957			// 已结束且有结束时记录：展示冻结的结束时信息，并对照最新状态。
958			rep.ItemsAtClose = true
959			rep.CloseItems = make([]CloseItemSnapshot, len(sh.CloseRecord.Items))
960			for i, s := range sh.CloseRecord.Items {
961				rep.CloseItems[i] = cloneCloseItemSnapshot(s)
962			}
963			sort.Slice(rep.CloseItems, func(i, j int) bool { return rep.CloseItems[i].ItemID < rep.CloseItems[j].ItemID })
964			for _, s := range rep.CloseItems {
965				if it, _ := findItem(d, s.ItemID); it != nil {
966					rep.LatestItems[s.ItemID] = cloneItem(*it)
967				}
968			}
969		default:
970			// 旧数据：结束时未留下记录，只能展示当前信息，不能宣称是结束时事实。
971			rep.HistoryIncomplete = true
972			rep.Items = currentItemsOfShift(d, sh.ID)
973		}
974		sort.Slice(rep.Items, func(i, j int) bool { return rep.Items[i].ID < rep.Items[j].ID })
975		for i := range rep.Items {
976			rep.Items[i] = cloneItem(rep.Items[i])
977		}
978	
979		for i := range d.Handovers {
980			h := &d.Handovers[i]
981			involved := h.FromShiftID == sh.ID || h.ToShiftID == sh.ID
982			if !involved {
983				continue
984			}
985			if h.FromShiftID == sh.ID {
986				cp := cloneHandover(*h)
987				rep.Outgoing = &cp
988			}
989			if h.ToShiftID == sh.ID {
990				rep.Incoming = append(rep.Incoming, cloneHandover(*h))
991			}
992			for j := range h.Entries {
993				rep.Results[h.Entries[j].ItemID] = append(rep.Results[h.Entries[j].ItemID], EntryView{
994					HandoverID: h.ID,
995					FromShift:  h.FromShiftID,
996					ToShift:    h.ToShiftID,
997					Entry:      cloneEntry(h.Entries[j]),
998				})
999			}
1000		}
1001		sort.Slice(rep.Incoming, func(i, j int) bool { return rep.Incoming[i].ID < rep.Incoming[j].ID })
1002		for k := range rep.Results {
1003			sort.Slice(rep.Results[k], func(i, j int) bool { return rep.Results[k][i].HandoverID < rep.Results[k][j].HandoverID })
1004		}
1005		return rep, nil
1006	}
