1	package handover
2	
3	import (
4		"fmt"
5		"sort"
6		"strings"
7		"time"
8	)
9	
10	const displayTime = "2006-01-02 15:04:05 -07:00"
11	
12	func fmtTime(t time.Time) string { return t.Format(displayTime) }
13	
14	func fmtTimePtr(t *time.Time) string {
15		if t == nil {
16			return "-"
17		}
18		return fmtTime(*t)
19	}
20	
21	// FormatShift 格式化班次摘要。
22	func FormatShift(sh Shift) string {
23		state := "进行中"
24		if sh.Closed {
25			state = "已结束 " + fmtTimePtr(sh.ClosedAt)
26		}
27		return fmt.Sprintf("%s  岗位=%s  负责人=%s  %s ~ %s  [%s]",
28			sh.ID, sh.Position, sh.Owner, fmtTime(sh.Start), fmtTime(sh.End), state)
29	}
30	
31	// FormatItem 格式化事项及其关闭情况与历史。
32	func FormatItem(it Item) string {
33		var b strings.Builder
34		writeItemHeader(&b, it)
35		if len(it.Events) > 0 {
36			b.WriteString("  历史：\n")
37			for _, ev := range it.Events {
38				who := ""
39				if ev.Operator != "" {
40					who = " 操作人=" + ev.Operator
41				}
42				detail := ""
43				if ev.Detail != "" {
44					detail = " " + ev.Detail
45				}
46				fmt.Fprintf(&b, "    - %s %s%s%s\n", fmtTime(ev.At), ev.Kind, who, detail)
47			}
48		}
49		return b.String()
50	}
51	
52	// writeItemHeader 输出事项的最新内容、严重程度、限制条件、后续负责人、
53	// 当前所在班次、关闭情况和流经班次。
54	func writeItemHeader(b *strings.Builder, it Item) {
55		state := "未关闭"
56		if it.Closed {
57			state = formatClosedState("已关闭", it.CloseOperator, it.ClosedAt)
58		}
59		fmt.Fprintf(b, "%s  严重程度=%s  当前班次=%s  原始班次=%s  [%s]\n",
60			it.ID, it.Severity.Label(), it.CurrentShiftID, it.OriginShiftID, state)
61		fmt.Fprintf(b, "  内容：%s\n", it.Content)
62		fmt.Fprintf(b, "  限制条件：%s\n", dashIfEmpty(it.Constraints))
63		fmt.Fprintf(b, "  后续负责人：%s\n", it.FollowOwner)
64		fmt.Fprintf(b, "  流经班次：%s\n", strings.Join(it.ShiftIDs, " -> "))
65	}
66	
67	func dashIfEmpty(s string) string {
68		if s == "" {
69			return "-"
70		}
71		return s
72	}
73	
74	// whoIfRecorded 展示操作人，未记录时明确标为未记录，不以其他人代替。
75	func whoIfRecorded(s string) string {
76		if s == "" {
77			return "未记录"
78		}
79		return s
80	}
81	
82	// fmtTimePtrIfRecorded 展示时间指针，缺失时明确标为未记录。
83	func fmtTimePtrIfRecorded(t *time.Time) string {
84		if t == nil {
85			return "未记录"
86		}
87		return fmtTimeIfRecorded(*t)
88	}
89	
90	// fmtTimeIfRecorded 展示时间值，旧数据零值（0001-01-01T00:00:00Z）时
91	// 明确标为未记录，不显示公元元年日期。
92	func fmtTimeIfRecorded(t time.Time) string {
93		if t.IsZero() {
94			return "未记录"
95		}
96		return fmtTime(t)
97	}
98	
99	// fmtProcessedAtIfRecorded 展示处理时间，缺失（nil）或旧数据零值
100	// （0001-01-01T00:00:00Z）时明确标为未记录，不推测补齐。
101	func fmtProcessedAtIfRecorded(t *time.Time) string {
102		if t == nil || t.IsZero() {
103			return "未记录"
104		}
105		return fmtTime(*t)
106	}
107	
108	// formatClosedState 是事项关闭信息在展示层的统一解读，item-show 的最新状态与
109	// shift-show 的当前事项、结束时记录、最新状态对照共用，保证同一份关闭信息在
110	// 各处解释一致。prefix 为“已关闭”或“结束时已关闭”。
111	//
112	// 只按已保存事实展示，不补齐、不推测：
113	//   - 事项保存的关闭状态为已关闭时，结论固定为已关闭，不能因为关闭人或关闭
114	//     时间缺失而改成未关闭；保存状态为未关闭时由调用方另行展示，残留的关闭人
115	//     或时间不作为一次有效关闭；
116	//   - 关闭人未保存或为空显示“未记录”；关闭时间未保存（nil）或为旧数据零值
117	//     （0001-01-01T00:00:00Z）同样显示“未记录”，不显示横线或公元元年日期；
118	//   - 姓名与时间分别判断：有姓名无时间保留姓名并指出关闭时间未记录，有真实
119	//     时间无姓名保留带时区的实际时间并指出关闭人未记录，缺一个不隐藏另一个，
120	//     也不以班次负责人或处理经过中的信息代替；
121	//   - 两者都有记录时沿用原有“姓名 于 时间”格式。
122	func formatClosedState(prefix, operator string, closedAt *time.Time) string {
123		hasOperator := operator != ""
124		hasTime := closedAt != nil && !closedAt.IsZero()
125		switch {
126		case hasOperator && hasTime:
127			return fmt.Sprintf("%s（%s 于 %s）", prefix, operator, fmtTime(*closedAt))
128		case hasOperator:
129			return fmt.Sprintf("%s（关闭人 %s，关闭时间未记录）", prefix, operator)
130		case hasTime:
131			return fmt.Sprintf("%s（关闭人未记录，关闭时间 %s）", prefix, fmtTime(*closedAt))
132		default:
133			return prefix + "（关闭人未记录，关闭时间未记录）"
134		}
135	}
136	
137	// currentProcessing 返回交接单项当前处理结果的处理人与处理时间展示，是
138	// 交接清单（handover-show、shift-show 内嵌清单与末尾结果说明）和事项处理
139	// 经过查询（item-show）共用的同一条业务规则。
140	//
141	// 是否处理过以已保存的处理结果（状态）为准，与处理时间是否保存无关：确认
142	// 接收、继续跟踪与退回都属于已经发生的处理，缺少处理时间不能使它们变成待
143	// 处理；真正待处理（含退回后已补充重新提交、等待接班人再次处理）的事项，
144	// 处理人与处理时间都显示尚未处理，即使旧记录残留姓名或时间也不显示成已处理。
145	//
146	// 已处理时处理人与处理时间各自独立展示：人名有值展示原姓名、缺失明确标为
147	// 未记录；时间有真实值沿用带时区格式、缺失或为旧数据零值
148	// （0001-01-01T00:00:00Z）同样标为未记录。缺少其中一个不能隐藏另一个，
149	// 也不以班次负责人、交接发起时间或退回历史中的信息代替。结果为空或无法
150	// 识别的记录同样按各自已保存的姓名与时间展示，不据以推测接收结果。
151	func currentProcessing(e HandoverEntry) (operator, processedAt string) {
152		if e.Status == EntryPending {
153			return "尚未处理", "尚未处理"
154		}
155		return whoIfRecorded(e.Operator), fmtProcessedAtIfRecorded(e.ProcessedAt)
156	}
157	
158	// returnRoundView 是一轮退回历史在展示层的统一解读。交接查询
159	// （handover-show，及 shift-show 报告内嵌的交接清单）与班次报告末尾
160	// “各项交接当前结果”两处共用同一份判断，只保留各自的措辞、缩进与
161	// 字段次序——统一维护的是共同规则，不是把两处改成同一种文本。
162	type returnRoundView struct {
163		Seq            int
164		ReturnedAt     string // 退回时间：真实值用带时区格式；缺失或零值显示未记录
165		ReturnOperator string // 退回人：有值保留原姓名，缺失显示未记录
166		Reason         string // 该轮保存的退回原因，原样展示
167	
168		HasSupplement      bool   // 该轮是否保存了非空补充说明；没有就不产生补充段落
169		Supplement         string // 该轮保存的补充说明
170		SupplementOperator string // 补充人：缺失显示未记录
171		SupplementAt       string // 补充时间：缺失（nil）或零值显示未记录
172	
173		Resubmitted   bool   // 该轮是否保存了重新提交时间（旧数据零值也算已重新提交）
174		ResubmittedAt string // 重新提交时间：零值显示未记录；未保存时不展示该行
175	}
176	
177	// viewReturnRound 按共同规则解读一轮已保存的退回历史。它只做展示判断，
178	// 不补齐、不推测：
179	//   - 姓名有值保留原姓名、缺失显示未记录；时间缺失或为旧数据零值
180	//     （0001-01-01T00:00:00Z）显示未记录，真实时间沿用带时区格式，
181	//     姓名与时间各自独立判断，缺一个不隐藏另一个；
182	//   - 不用班次负责人、交接发起时间、当前处理人或其他轮次的资料补齐
183	//     本轮记录；
184	//   - 该轮没有非空补充说明时不产生补充段落；没有重新提交时间时不显示
185	//     已重新提交；保存了零值重新提交时间仍按已重新提交展示、时间显示
186	//     未记录，不悄悄改成尚未提交。
187	func viewReturnRound(r ReturnRound) returnRoundView {
188		v := returnRoundView{
189			Seq:            r.Seq,
190			ReturnedAt:     fmtTimeIfRecorded(r.ReturnedAt),
191			ReturnOperator: whoIfRecorded(r.ReturnOperator),
192			Reason:         r.Reason,
193			Resubmitted:    r.ResubmittedAt != nil,
194			ResubmittedAt:  fmtTimePtrIfRecorded(r.ResubmittedAt),
195		}
196		if r.Supplement != "" {
197			v.HasSupplement = true
198			v.Supplement = r.Supplement
199			v.SupplementOperator = whoIfRecorded(r.SupplementOperator)
200			v.SupplementAt = fmtTimePtrIfRecorded(r.SupplementAt)
201		}
202		return v
203	}
204	
205	// viewReturnRounds 按保存次序解读全部退回轮次，不增删、不重排、不补造：
206	// 连续发生多轮退回时每轮各用各的退回原因与补充说明，前一轮的原因和
207	// 补充不会被后一轮替换；没有退回轮次时返回空切片，调用方不补造轮次。
208	func viewReturnRounds(rounds []ReturnRound) []returnRoundView {
209		vs := make([]returnRoundView, len(rounds))
210		for i, r := range rounds {
211			vs[i] = viewReturnRound(r)
212		}
213		return vs
214	}
215	
216	// entryCurrentResultLabel 是交接当前结果在事项处理经过查询中的展示名。
217	// 缺失或空结果显示“处理结果未记录”，无法识别的结果显示“处理结果无法识别”
218	// 并带出保存的原值，与交接清单、班次报告表达同一事实，不推测成已接收。
219	func entryCurrentResultLabel(s EntryStatus) string {
220		switch s {
221		case EntryPending:
222			return "待处理（接班人尚未处理）"
223		case EntryReturned:
224			return "退回（等待交班人补充）"
225		case EntryConfirmed:
226			return "确认接收"
227		case EntryTracking:
228			return "继续跟踪（已接收）"
229		case "":
230			return "处理结果未记录"
231		}
232		return "处理结果无法识别（原值：" + string(s) + "）"
233	}
234	
235	// FormatJourneyEvent 格式化处理经过中的单条记录。交接相关记录带有交接
236	// 编号与交班、接班班次；缺少的人名或时间明确标为未记录，不推测补齐。
237	func FormatJourneyEvent(ev JourneyEvent) string {
238		when := "未记录"
239		if ev.TimeKnown {
240			when = fmtTime(ev.At)
241		}
242		who := whoIfRecorded(ev.Operator)
243		where := ""
244		if ev.HandoverID != "" {
245			where = fmt.Sprintf("交接 %s（%s -> %s）", ev.HandoverID, ev.FromShift, ev.ToShift)
246		}
247		switch ev.Kind {
248		case "created":
249			return when + " 事项建立"
250		case "updated":
251			return fmt.Sprintf("%s 修改：%s", when, ev.Detail)
252		case "closed":
253			return fmt.Sprintf("%s 关闭 操作人=%s", when, who)
254		case "received":
255			return fmt.Sprintf("%s 接收 操作人=%s %s", when, who, ev.Detail)
256		case "handover-init":
257			// 交接发起不记录操作人，始终显示未记录，不以班次负责人代替。
258			return fmt.Sprintf("%s %s发起交接 操作人=%s", when, where, who)
259		case "return":
260			return fmt.Sprintf("%s %s第%d次退回 操作人=%s 原因=%s",
261				when, where, ev.RoundSeq, who, ev.Reason)
262		case "return-incomplete":
263			// 当前结果是退回却没有退回轮次记录：退回确实发生过，但轮次序号、
264			// 退回原因、补充与重新提交经过都没有可靠记录。处理人与时间各自使用
265			// 当前保存的信息（缺失分别标为未记录），并明确提示退回历史不完整、
266			// 原因未记录，不编造第几次退回，也不拿事项内容代替原因。
267			return fmt.Sprintf("%s %s退回 操作人=%s（退回历史不完整：缺少退回轮次记录，退回原因未记录）",
268				when, where, who)
269		case "resubmit":
270			return fmt.Sprintf("%s %s第%d次重新提交 补充说明=%s 补充人=%s 补充时间=%s",
271				when, where, ev.RoundSeq, dashIfEmpty(ev.Supplement),
272				whoIfRecorded(ev.SupplementOperator), fmtTimePtrIfRecorded(ev.SupplementAt))
273		case "confirm":
274			return fmt.Sprintf("%s %s确认接收 操作人=%s", when, where, who)
275		case "track":
276			return fmt.Sprintf("%s %s继续跟踪 操作人=%s 跟踪说明=%s 后续负责人=%s",
277				when, where, who, dashIfEmpty(ev.TrackingNote), dashIfEmpty(ev.FollowOwner))
278		}
279		return when + " " + ev.Kind
280	}
281	
282	// FormatItemJourney 格式化凭事项编号查询得到的完整处理经过：开头为事项
283	// 最新状态，随后是合并事项自身历史与各次交接经过的时间线，最后列出该事项
284	// 在每次交接中的当前处理结果；尚未参与交接的显示暂无交接记录。
285	func FormatItemJourney(j ItemJourney) string {
286		var b strings.Builder
287		writeItemHeader(&b, j.Item)
288	
289		b.WriteString("  处理经过：\n")
290		if len(j.Events) == 0 {
291			b.WriteString("    （暂无记录）\n")
292		}
293		for _, ev := range j.Events {
294			b.WriteString("    - " + FormatJourneyEvent(ev) + "\n")
295		}
296	
297		b.WriteString("  交接当前结果：\n")
298		if !j.HasHandovers {
299			b.WriteString("    暂无交接记录\n")
300		}
301		for _, r := range j.Results {
302			// 处理人与处理时间沿用共用的当前处理展示规则（见 currentProcessing）。
303			operator, processedAt := currentProcessing(r.Entry)
304			fmt.Fprintf(&b, "    交接 %s（%s -> %s）当前结果：%s；处理人=%s；处理时间=%s\n",
305				r.HandoverID, r.FromShift, r.ToShift,
306				entryCurrentResultLabel(r.Entry.Status), operator, processedAt)
307		}
308		return b.String()
309	}
310	
311	// FormatCloseItem 格式化班次结束时冻结的事项记录，并与最新状态对照。
312	func FormatCloseItem(snap CloseItemSnapshot, latest *Item) string {
313		var b strings.Builder
314		state := "结束时未关闭"
315		if snap.Closed {
316			state = formatClosedState("结束时已关闭", snap.CloseOperator, snap.ClosedAt)
317		}
318		fmt.Fprintf(&b, "%s  严重程度=%s  %s\n", snap.ItemID, snap.Severity.Label(), state)
319		fmt.Fprintf(&b, "  内容：%s\n", snap.Content)
320		fmt.Fprintf(&b, "  限制条件：%s\n", dashIfEmpty(snap.Constraints))
321		fmt.Fprintf(&b, "  结束时后续负责人：%s\n", snap.FollowOwner)
322		if latest == nil {
323			b.WriteString("  最新状态：事项记录已不存在\n")
324			return b.String()
325		}
326		closeState := "未关闭"
327		if latest.Closed {
328			closeState = formatClosedState("已关闭", latest.CloseOperator, latest.ClosedAt)
329		}
330		fmt.Fprintf(&b, "  最新状态：当前所在班次=%s  最新负责人=%s  最新关闭情况=%s\n",
331			latest.CurrentShiftID, latest.FollowOwner, closeState)
332		return b.String()
333	}
334	
335	// FormatOverlapNote 格式化重叠说明。
336	func FormatOverlapNote(n OverlapNote) string {
337		return fmt.Sprintf("%s  岗位=%s  班次 %s <-> %s  %s\n  说明：%s",
338			n.ID, n.Position, n.ShiftA, n.ShiftB, fmtTime(n.CreatedAt), n.Note)
339	}
340	
341	// FormatEntry 格式化交接单项当前结果与历次退回、补充说明。
342	func FormatEntry(e HandoverEntry) string {
343		var b strings.Builder
344		fmt.Fprintf(&b, "%s  [%s]  严重程度=%s  后续负责人=%s\n",
345			e.ItemID, e.Status.Label(), e.Severity.Label(), e.FollowOwner)
346		fmt.Fprintf(&b, "  原文：%s\n", e.Content)
347		fmt.Fprintf(&b, "  限制条件：%s\n", dashIfEmpty(e.Constraints))
348		// 处理人与处理时间沿用共用的当前处理展示规则（见 currentProcessing）；
349		// 待处理项在此额外说明等待接班人处理。
350		operator, processedAt := currentProcessing(e)
351		if e.Status == EntryPending {
352			fmt.Fprintf(&b, "  最后处理：尚未处理（等待接班人处理）；处理人=%s；处理时间=%s\n",
353				operator, processedAt)
354		} else {
355			fmt.Fprintf(&b, "  最后处理：处理人=%s；处理时间=%s\n", operator, processedAt)
356		}
357		if e.Status == EntryTracking || e.TrackingNote != "" {
358			fmt.Fprintf(&b, "  跟踪说明：%s\n", dashIfEmpty(e.TrackingNote))
359			fmt.Fprintf(&b, "  跟踪后续负责人：%s\n", dashIfEmpty(e.FollowOwner))
360		}
361		// 逐轮退回、补充与重新提交沿用共用的退回历史解读规则
362		// （见 viewReturnRound），保留本处原有措辞、缩进与字段次序。
363		for _, r := range viewReturnRounds(e.Rounds) {
364			fmt.Fprintf(&b, "  第%d次退回：%s 操作人=%s 原因=%s\n",
365				r.Seq, r.ReturnedAt, r.ReturnOperator, r.Reason)
366			if r.HasSupplement {
367				fmt.Fprintf(&b, "    补充说明：%s 补充人=%s 补充时间=%s\n",
368					r.Supplement, r.SupplementOperator, r.SupplementAt)
369			}
370			if r.Resubmitted {
371				fmt.Fprintf(&b, "    已重新提交：%s\n", r.ResubmittedAt)
372			}
373		}
374		return b.String()
375	}
376	
377	// FormatHandover 格式化完整交接记录。
378	func FormatHandover(h Handover) string {
379		var b strings.Builder
380		state := "未完成"
381		if h.Completed() {
382			state = "已完成 " + fmtTimePtrIfRecorded(h.CompletedAt)
383		}
384		fmt.Fprintf(&b, "%s  岗位=%s  %s -> %s  发起于 %s  [%s]  共%d项\n",
385			h.ID, h.Position, h.FromShiftID, h.ToShiftID,
386			fmtTimeIfRecorded(h.CreatedAt), state, len(h.Entries))
387		if len(h.Entries) == 0 {
388			b.WriteString("  （空清单，直接完成）\n")
389		}
390		for i := range h.Entries {
391			b.WriteString(indentLines(FormatEntry(h.Entries[i]), "  "))
392		}
393		return b.String()
394	}
395	
396	func indentLines(s, prefix string) string {
397		return prefix + strings.ReplaceAll(strings.TrimRight(s, "\n"), "\n", "\n"+prefix) + "\n"
398	}
399	
400	// FormatReport 格式化按班次查询的完整报告。
401	func FormatReport(rep ShiftReport) string {
402		var b strings.Builder
403		b.WriteString("班次 " + FormatShift(rep.Shift) + "\n")
404	
405		b.WriteString("\n重叠说明：\n")
406		if len(rep.OverlapNotes) == 0 {
407			b.WriteString("  （无）\n")
408		}
409		for _, n := range rep.OverlapNotes {
410			b.WriteString(indentLines(FormatOverlapNote(n), "  "))
411		}
412	
413		if rep.ItemsAtClose {
414			b.WriteString("\n事项（以下为结束时记录，冻结于该班结束成功时刻；后班的修改、关闭与交接不改变本记录）：\n")
415			if len(rep.CloseItems) == 0 {
416				b.WriteString("  （结束时没有事项）\n")
417			}
418			for _, s := range rep.CloseItems {
419				var latest *Item
420				if v, ok := rep.LatestItems[s.ItemID]; ok {
421					latest = &v
422				}
423				b.WriteString(indentLines(FormatCloseItem(s, latest), "  "))
424			}
425		} else {
426			if rep.HistoryIncomplete {
427				b.WriteString("\n事项（历史记录不完整，该班结束时未留下记录，以下为当前信息，不能视为结束时事实）：\n")
428			} else {
429				b.WriteString("\n事项：\n")
430			}
431			if len(rep.Items) == 0 {
432				b.WriteString("  （无）\n")
433			}
434			for _, it := range rep.Items {
435				b.WriteString(indentLines(FormatItem(it), "  "))
436			}
437		}
438	
439		b.WriteString("\n交班对象：\n")
440		if rep.Outgoing == nil {
441			b.WriteString("  （尚未发起交接）\n")
442		} else {
443			b.WriteString(indentLines(FormatHandover(*rep.Outgoing), "  "))
444		}
445	
446		b.WriteString("\n接班交接：\n")
447		if len(rep.Incoming) == 0 {
448			b.WriteString("  （无）\n")
449		}
450		for _, h := range rep.Incoming {
451			b.WriteString(indentLines(FormatHandover(h), "  "))
452		}
453	
454		b.WriteString("\n各项交接当前结果：\n")
455		if len(rep.Results) == 0 {
456			b.WriteString("  （无）\n")
457		}
458		ids := make([]string, 0, len(rep.Results))
459		for id := range rep.Results {
460			ids = append(ids, id)
461		}
462		sort.Strings(ids)
463		for _, id := range ids {
464			views := rep.Results[id]
465			for _, v := range views {
466				// 处理人与处理时间沿用共用的当前处理展示规则（见
467				// currentProcessing），与内嵌交接清单表达同一事实。
468				operator, processedAt := currentProcessing(v.Entry)
469				fmt.Fprintf(&b, "  事项 %s 交接 %s（%s -> %s）当前结果：%s；处理人=%s；处理时间=%s\n",
470					id, v.HandoverID, v.FromShift, v.ToShift,
471					v.Entry.Status.Label(), operator, processedAt)
472				// 退回历史与内嵌交接清单共用同一解读规则（见
473				// viewReturnRound），这里保留结果区原有的措辞、缩进与字段次序。
474				for _, r := range viewReturnRounds(v.Entry.Rounds) {
475					fmt.Fprintf(&b, "    第%d次退回：操作人=%s 时间=%s 原因=%s\n",
476						r.Seq, r.ReturnOperator, r.ReturnedAt, r.Reason)
477					if r.HasSupplement {
478						fmt.Fprintf(&b, "      补充：%s（补充人=%s，补充时间=%s）\n",
479							r.Supplement, r.SupplementOperator, r.SupplementAt)
480					}
481					if r.Resubmitted {
482						fmt.Fprintf(&b, "      已重新提交：%s\n", r.ResubmittedAt)
483					}
484				}
485			}
486		}
487		return b.String()
488	}
